// Work the engine schedules itself, outside JavaScript's own queues: FinalizationRegistry
// callbacks once their objects are collected, and WebAssembly compiled off the main thread.
// The same package under Node.js prints the same.
module.exports = function run() {
  const bytes = new Uint8Array([0, 97, 115, 109, 1, 0, 0, 0, 1, 7, 1, 96, 2, 127, 127, 1, 127, 3, 2, 1, 0, 7, 7, 1, 3, 97, 100, 100, 0, 0, 10, 9, 1, 7, 0, 32, 0, 32, 1, 106, 11]);
  WebAssembly.instantiate(bytes)
    .then((r) => {
      console.log("wasm add", r.instance.exports.add(2, 3));
      return WebAssembly.compile(bytes);
    })
    .then((m) => console.log("wasm exports", WebAssembly.Module.exports(m).map((e) => e.name).join()));

  const finalized = [];
  const registry = new FinalizationRegistry((held) => finalized.push(held));
  (function () {
    for (let i = 0; i < 3; i++) registry.register({ data: new Array(1000).fill(i) }, `object ${i}`);
  })();
  // (garbage until the engine collects them, or five seconds)
  const start = Date.now();
  const timer = setInterval(() => {
    for (let i = 0; i < 20; i++) new Array(10000).fill(i);
    if (finalized.length === 3 || Date.now() - start > 5000) {
      clearInterval(timer);
      console.log("finalized", finalized.sort().join(", "));
    }
  }, 20);
};
